head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 테스트용 suffix.txt 내용 (JSON 형식). 프로젝트 공통 파일을 바꾸지 않기 위해 XHR 요청 URL 만 바꿔 전달한다.
scwin.SUFFIX_JSON = '{"suffix":[{"path":"/langpack","defaults":"lang_${year}_${month}"},{"extension":{"js":"js_${day}","xml":"xml_${week}"},"defaults":"etc_${random}"}]}';

// suffix.txt 요청을 위 JSON 내용으로 바꿔 응답시키고, 호출이 끝나면 원상복구한다
scwin.redirectSuffixXHR = function (strBody) {
    var fnOrigOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (strMethod, strUrl) {
        if (typeof strUrl === "string" && strUrl.indexOf("suffix.txt") > -1) {
            arguments[1] = "data:text/plain;charset=utf-8," + encodeURIComponent(strBody);
        }
        return fnOrigOpen.apply(this, arguments);
    };
    return {
        restore : function () { XMLHttpRequest.prototype.open = fnOrigOpen; }
    };
};

// WebSquare.suffix 의 타입과 값을 한 줄로 요약
scwin.getSuffixState = function () {
    if (typeof WebSquare === "undefined" || typeof WebSquare.suffix === "undefined") {
        return "undefined (미설정)";
    }
    var objSuffix = WebSquare.suffix;
    if (objSuffix === null) {
        return "null";
    }
    if (typeof objSuffix === "string") {
        return "string : '" + objSuffix + "'";
    }
    if (typeof objSuffix === "object") {
        try { return "object : " + JSON.stringify(objSuffix); } catch (objError) { return "object"; }
    }
    return typeof objSuffix;
};

// WebSquare.suffix 가 어떤 형태로 보관됐는지
scwin.getSuffixType = function () {
    if (typeof WebSquare === "undefined" || typeof WebSquare.suffix === "undefined") return "undefined";
    if (WebSquare.suffix === null) return "null";
    if (typeof WebSquare.suffix === "string") return "string (JSON 원문이 문자열 그대로 들어 있다)";
    if (typeof WebSquare.suffix === "object") return "object (JSON 이 파싱되어 있다)";
    return typeof WebSquare.suffix;
};



// 특정 리소스 URL 에 실제로 붙는 postfix 문자열
scwin.getGeneratedPostfix = function (strUri) {
    try {
        if (WebSquare && WebSquare.BootLoader && typeof WebSquare.BootLoader.generateSuffixPostfix === "function") {
            return WebSquare.BootLoader.generateSuffixPostfix(strUri);
        }
    } catch (objError) { }
    return "(조회 불가)";
};

scwin.btn_updateSuffix_onclick = function (e) {
    var objHandle = scwin.redirectSuffixXHR(scwin.SUFFIX_JSON);

    scwin.setReturnValue("=====updateSuffix 호출 (suffix.txt 내용 = JSON 형식)=====");
    scwin.setReturnValue("[호출 전] WebSquare.suffix : " + scwin.getSuffixState());

    var objRet = $p.updateSuffix();

    var fnDone = function () {
        // 확인용 리소스 3종 : JSON 에 정의한 규칙이 각각 다르게 적용되어야 한다
        var arrProbe = [
            { uri : "/langpack/ko.js", rule : "path 규칙 (/langpack)" },
            { uri : "/common/grid.xml", rule : "extension 규칙 (xml)" },
            { uri : "/common/style.css", rule : "defaults 규칙" }
        ];

        scwin.setReturnValue("[호출 후] WebSquare.suffix 보관 타입 : " + scwin.getSuffixType());
        scwin.setReturnValue("");
        scwin.setReturnValue("----- 리소스에 실제로 만들어지는 URL -----");

        var arrPostfix = [];
        for (var i = 0; i < arrProbe.length; i++) {
            var strPostfix = scwin.getGeneratedPostfix(arrProbe[i].uri);
            arrPostfix.push(strPostfix);
            scwin.setReturnValue("· " + arrProbe[i].rule);
            scwin.setReturnValue("    " + arrProbe[i].uri + "?postfix=" + strPostfix);
            scwin.setReturnValue("    (postfix 길이 " + String(strPostfix).length + "자)");
        }

        // 세 리소스의 postfix 가 서로 달라야 규칙이 적용된 것이다
        var bAllSame = (arrPostfix[0] === arrPostfix[1] && arrPostfix[1] === arrPostfix[2]);
        scwin.setReturnValue("");
        scwin.setReturnValue("----- 판정 -----");
        scwin.setReturnValue("경로·확장자별 규칙 적용 여부 : " + (bAllSame ? "적용 안 됨 (세 리소스의 postfix 가 모두 같다)" : "적용됨 (리소스마다 postfix 가 다르다)"));

        objHandle.restore();
    };

    if (objRet && typeof objRet.then === "function") {
        objRet.then(fnDone, function (objError) {
            scwin.setReturnValue("reject : " + objError);
            objHandle.restore();
        });
    } else {
        setTimeout(fnDone, 700);
    }
};
